        )
    except Exception:
        MODELS_AVAILABLE = False

ResearchParsed = Union[BaseModel, Dict[str, Any]]

def is_pydantic_model(schema: Any) -> bool:
    try:
        return isinstance(schema, type) and issubclass(schema, BaseModel)
    except (TypeError, AttributeError):
        return False

def pydantic_to_json_schema(model: Type[BaseModel]) -> Dict[str, Any]:
    try:
        from exa_py.utils import _convert_schema_input
        return _convert_schema_input(model)
    except Exception:
        try:
            return model.model_json_schema()  # type: ignore[attr-defined]
        except Exception:
            try:
                return model.schema()  # type: ignore[attr-defined]
            except Exception:
                return {}

def parse_sse_line(line: str) -> Optional[tuple[str, str]]:
    if not line:
        return None
    if line.startswith(":"):
        return None
    if ":" not in line:
        field = line.strip()
        if not field:
            return None
        return field, ""
    field, _, value = line.partition(":")
    return field.strip(), value.lstrip()

def parse_sse_event_raw(event_lines: List[str]) -> Optional[Dict[str, Any]]:
    if not event_lines:
        return None
    event_name: Optional[str] = None
    event_id: Optional[str] = None
    retry_ms: Optional[int] = None
    data_parts: List[str] = []
    for line in event_lines:
        parsed = parse_sse_line(line)
        if not parsed:
            continue
        field, value = parsed
        if field == "event":
            event_name = value
        elif field == "data":
            data_parts.append(value)
        elif field == "id":
            event_id = value
        elif field == "retry":
            try:
                retry_ms = int(value)
            except ValueError:
                pass
    if not data_parts and event_name is None and event_id is None and retry_ms is None:
        return None
    raw_data = "\n".join(data_parts) if data_parts else ""
    if raw_data:
        try:
            event_data: Any = json.loads(raw_data)
        except json.JSONDecodeError:
            event_data = raw_data
    else:
        event_data = {}
    if isinstance(event_data, dict):
        if event_name:
            event_data["eventType"] = event_name
        else:
            event_data["eventType"] = "message"
        if event_id is not None:
            event_data["id"] = event_id
        if retry_ms is not None:
            event_data["retry"] = retry_ms
        return event_data
    result: Dict[str, Any] = {"data": event_data, "eventType": event_name or "message"}
    if event_id is not None:
        result["id"] = event_id
    if retry_ms is not None:
        result["retry"] = retry_ms
    return result

def parse_research_event(raw_event: Dict[str, Any]) -> Optional[ResearchParsed]:
    event_type = raw_event.get("eventType")
    if not event_type:
        return None
    if MODELS_AVAILABLE:
        event_models: Dict[str, Type[BaseModel]] = {
            "research-definition": ResearchDefinitionEvent,  # type: ignore[name-defined]
            "research-output": ResearchOutputEvent,  # type: ignore[name-defined]
            "plan-definition": ResearchPlanDefinitionEvent,  # type: ignore[name-defined]
            "plan-operation": ResearchPlanOperationEvent,  # type: ignore[name-defined]
            "plan-output": ResearchPlanOutputEvent,  # type: ignore[name-defined]
            "task-definition": ResearchTaskDefinitionEvent,  # type: ignore[name-defined]
            "task-operation": ResearchTaskOperationEvent,  # type: ignore[name-defined]
            "task-output": ResearchTaskOutputEvent,  # type: ignore[name-defined]
        }
        model_class = event_models.get(event_type)
        if not model_class:
            return None
        try:
            return model_class.model_validate(raw_event)  # type: ignore[attr-defined]
        except ValidationError:
            return None
        except AttributeError:
            try:
                return model_class.parse_obj(raw_event)  # type: ignore[attr-defined]
            except Exception:
                return None
    return raw_event

def stream_sse_events(response: requests.Response) -> Generator[ResearchParsed, None, None]:
    event_lines: List[str] = []
    for line in response.iter_lines(decode_unicode=True):
        if line is None:
            continue
        if line == "":
            if event_lines:
                raw_event = parse_sse_event_raw(event_lines)
                if raw_event:
                    parsed = parse_research_event(raw_event)
                    if parsed is not None:
                        yield parsed
                event_lines = []
        else:
            event_lines.append(line)
    if event_lines:
        raw_event = parse_sse_event_raw(event_lines)
        if raw_event:
            parsed = parse_research_event(raw_event)
            if parsed is not None:
                yield parsed

